import { PageHeader } from '@gntik-ai/blocks';
import { ArrowRight, Rss } from '@gntik-ai/icons';
import {
  Badge,
  Button,
  EmptyState,
  Heading,
  HStack,
  Link,
  Page,
  Stack,
  Text,
  Timestamp,
  Toggle,
  ToggleGroup,
  type BreadcrumbItem,
} from '@gntik-ai/ui';
import { useId, useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { changelogBreadcrumbs, changelogEntries, changelogTagLabels, changelogTagTones, type ChangelogEntry, type ChangelogTag } from './data';

export interface ChangelogProps {
  title: string;
  description: string;
  /** Entries, newest first. */
  entries: ChangelogEntry[];
  /** Tags initially pressed; none = every entry. */
  defaultTags: ChangelogTag[];
  onTagsChange: (tags: ChangelogTag[]) => void;
  /** Subscribe action (RSS, email…); omit to hide it. */
  onSubscribe: (() => void) | null;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  shell: Omit<ConsoleShellProps, 'children'>;
}

const isTag = (v: string): v is ChangelogTag => v in changelogTagLabels;

/** Changelog: dated release entries with tag badges and a "New" badge, filtered by tag. */
export default function ChangelogPage(props: Partial<ChangelogProps>) {
  const {
    title = 'Changelog',
    description = 'New features, improvements and fixes, newest first.',
    entries = changelogEntries,
    defaultTags = [],
    onTagsChange,
    onSubscribe = () => {},
    breadcrumbs = changelogBreadcrumbs,
    currentHref = '/help/changelog',
    shell,
  } = props;
  const [tags, setTags] = useState<ChangelogTag[]>(defaultTags);
  const countId = useId();
  const tagsInUse = (Object.keys(changelogTagLabels) as ChangelogTag[]).filter((t) => entries.some((e) => e.tags.includes(t)));
  const visible = tags.length === 0 ? entries : entries.filter((e) => e.tags.some((t) => tags.includes(t)));

  const changeTags = (next: string[]) => {
    const valid = next.filter(isTag);
    setTags(valid);
    onTagsChange?.(valid);
  };

  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description={description}
            status=""
            meta={[]}
            tabs={null}
            actions={onSubscribe ? [{ label: 'Subscribe', icon: Rss, variant: 'secondary', onClick: onSubscribe }] : []}
          />
        }
      >
        <Stack gap={8}>
          <HStack gap={3} wrap>
            <ToggleGroup aria-label="Filter by tag" aria-describedby={countId} size="sm" multiple value={tags} onValueChange={changeTags}>
              {tagsInUse.map((t) => (
                <Toggle key={t} value={t}>
                  {changelogTagLabels[t]}
                </Toggle>
              ))}
            </ToggleGroup>
            {tags.length > 0 && (
              <Button variant="ghost" size="sm" onClick={() => changeTags([])}>
                Show all
              </Button>
            )}
            <Text id={countId} as="span" variant="caption" tone="muted" aria-live="polite">
              {visible.length === 1 ? '1 release' : `${visible.length} releases`}
            </Text>
          </HStack>
          {visible.length === 0 ? (
            <EmptyState size="sm" titleAs="h2" title="No releases with these tags" description="Pick another tag or show every release." />
          ) : (
            <ol aria-label="Releases" className="flex flex-col divide-y divide-border">
              {visible.map((e) => (
                <li key={e.id} className="grid gap-3 py-7 first:pt-0 md:grid-cols-[10rem_1fr] md:gap-8">
                  <Stack gap={1}>
                    <Timestamp value={e.date} format="absolute" tooltip={false} dateOptions={{ dateStyle: 'medium' }} className="text-[13px] font-medium text-foreground" />
                    <Text as="span" variant="caption" tone="muted" className="font-mono">
                      v{e.version}
                    </Text>
                  </Stack>
                  <article aria-labelledby={`${countId}-${e.id}`}>
                    <Stack gap={3}>
                      <HStack gap={2} wrap>
                        {e.isNew && (
                          <Badge tone="primary" variant="solid">
                            New
                          </Badge>
                        )}
                        {e.tags.map((t) => (
                          <Badge key={t} tone={changelogTagTones[t]}>
                            {changelogTagLabels[t]}
                          </Badge>
                        ))}
                      </HStack>
                      <Heading id={`${countId}-${e.id}`} level={2} size="sm">
                        {e.title}
                      </Heading>
                      <Text tone="muted">{e.summary}</Text>
                      <ul className="flex list-disc flex-col gap-1.5 ps-5 text-[13.5px] leading-6 text-foreground marker:text-muted-foreground">
                        {e.changes.map((c) => (
                          <li key={c}>{c}</li>
                        ))}
                      </ul>
                      {e.href && (
                        <Link href={e.href} className="inline-flex items-center gap-1 self-start text-[13px]">
                          Read the release notes <ArrowRight size={14} aria-hidden />
                          <span className="sr-only"> for {e.version}</span>
                        </Link>
                      )}
                    </Stack>
                  </article>
                </li>
              ))}
            </ol>
          )}
        </Stack>
      </Page>
    </ConsoleShell>
  );
}

import type { BadgeProps, BreadcrumbItem } from '@gntik-ai/ui';

export type ChangelogTag = 'feature' | 'improvement' | 'fix' | 'security' | 'deprecation';

export interface ChangelogEntry {
  id: string;
  /** Release version, e.g. "2.14". */
  version: string;
  date: string;
  title: string;
  summary: string;
  /** Bullet list of changes. */
  changes: string[];
  tags: ChangelogTag[];
  /** Shows the "New" badge (e.g. released since the viewer's last visit). */
  isNew?: boolean;
  /** "Read more" link. */
  href?: string;
}

export const changelogTagLabels: Record<ChangelogTag, string> = {
  feature: 'Feature',
  improvement: 'Improvement',
  fix: 'Fix',
  security: 'Security',
  deprecation: 'Deprecation',
};

export const changelogTagTones: Record<ChangelogTag, NonNullable<BadgeProps['tone']>> = {
  feature: 'primary',
  improvement: 'info',
  fix: 'neutral',
  security: 'warning',
  deprecation: 'destructive',
};

export const changelogBreadcrumbs: BreadcrumbItem[] = [{ label: 'Help', href: '/help' }, { label: 'Changelog' }];

/** Neutral release notes, newest first. */
export const changelogEntries: ChangelogEntry[] = [
  {
    id: 'v2-14',
    version: '2.14',
    date: '2026-09-29',
    title: 'Deploy gates and scheduled rollbacks',
    summary: 'Block releases while an incident is open, and schedule a rollback for a quiet hour.',
    changes: [
      'Deploy gates check open incidents, failing checks and freeze windows before every release.',
      'Rollbacks can be scheduled; the deployment page shows a countdown and a cancel action.',
      'The deployments table remembers its density and hidden columns per project.',
    ],
    tags: ['feature', 'improvement'],
    isNew: true,
    href: '/changelog/v2-14',
  },
  {
    id: 'v2-13-2',
    version: '2.13.2',
    date: '2026-09-18',
    title: 'Stricter API key scopes',
    summary: 'New keys default to read-only; existing keys keep their scopes.',
    changes: ['Keys created from now on start read-only.', 'Audit log entries now include the key’s last four characters.'],
    tags: ['security'],
    isNew: true,
  },
  {
    id: 'v2-13-1',
    version: '2.13.1',
    date: '2026-09-07',
    title: 'Fixes for usage exports',
    summary: 'CSV exports respect the selected range and time zone again.',
    changes: ['Exports used UTC instead of the workspace time zone.', 'Large exports no longer time out after 30 seconds.'],
    tags: ['fix'],
  },
  {
    id: 'v2-13',
    version: '2.13',
    date: '2026-08-25',
    title: 'Saved views for every table',
    summary: 'Save filters, sorting and columns as a view, and share it with your workspace.',
    changes: ['Saved views on projects, deployments, members and invoices.', 'Views can be private or shared with the workspace.'],
    tags: ['feature'],
  },
  {
    id: 'v2-12',
    version: '2.12',
    date: '2026-08-04',
    title: 'Legacy webhooks are deprecated',
    summary: 'Version 1 webhooks stop on 1 December 2026. Move to signed webhooks before then.',
    changes: ['Signed webhooks include a timestamp and an HMAC header.', 'The integrations page lists every endpoint still on version 1.'],
    tags: ['deprecation', 'security'],
  },
];

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
